// Cockpit ITSM public API - core of the Java access classes generated by CIPAT
// (Cockpit ITSM Public API Toolkit). Written next to the generated
// class at each generation: do not edit (changes would be overwritten).
//
// - OAuth 2.0 token (client_credentials, multipart/form-data, scope public-api),
//   renewed before expiry and once more on a 401 response;
// - HTTP: java.net.http.HttpClient (Java 11+), replaceable (setHttpClient), e.g.
//   by a client accepting a self-signed certificate;
// - paged lists: every page read, items merged and truncated to
//   totalNumberOfElements (fetchAllPages);
// - JSON: org.json (JSONObject / JSONArray), plus the conversion helpers used by
//   the generated classes. Missing or null members are read as null.

import java.math.BigDecimal;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

import org.json.JSONArray;
import org.json.JSONObject;
import org.json.JSONTokener;

public class CockpitItsmCore {

    /** Error of a Cockpit ITSM call: HTTP status (0 = network error or invalid response) and response body. */
    public static class CockpitItsmException extends RuntimeException {
        private static final long serialVersionUID = 1L;
        private final int statusCode;
        private final String response;

        public CockpitItsmException(int statusCode, String message, String response) {
            super(message);
            this.statusCode = statusCode;
            this.response = response == null ? "" : response;
        }

        public CockpitItsmException(int statusCode, String message, String response, Throwable cause) {
            super(message, cause);
            this.statusCode = statusCode;
            this.response = response == null ? "" : response;
        }

        public int getStatusCode() { return statusCode; }
        public String getResponse() { return response; }
    }

    private static final int DEFAULT_PAGE_SIZE = 500;
    private static final int TOKEN_MARGIN_SEC = 60;

    private boolean saas = true;
    private String tenant = "";
    private String clientId = "";
    private String clientSecret = "";
    private String accessToken = "";
    private Instant tokenExpiry = Instant.EPOCH;
    private int pageSize = DEFAULT_PAGE_SIZE;
    private Duration timeout = Duration.ofSeconds(60);
    private int lastStatus;
    private HttpClient httpClient;

    public CockpitItsmCore() {
    }

    public CockpitItsmCore(boolean saas, String tenant, String clientId, String clientSecret) {
        this.saas = saas;
        this.tenant = tenant == null ? "" : tenant;
        this.clientId = clientId == null ? "" : clientId;
        this.clientSecret = clientSecret == null ? "" : clientSecret;
    }

    // ------------------------------------------------------------------ settings

    public boolean isSaas() { return saas; }
    public void setSaas(boolean value) { if (value != saas) { saas = value; clearToken(); } }
    public String getTenant() { return tenant; }
    public void setTenant(String value) { value = value == null ? "" : value; if (!value.equals(tenant)) { tenant = value; clearToken(); } }
    public String getClientId() { return clientId; }
    public void setClientId(String value) { value = value == null ? "" : value; if (!value.equals(clientId)) { clientId = value; clearToken(); } }
    public String getClientSecret() { return clientSecret; }
    public void setClientSecret(String value) { value = value == null ? "" : value; if (!value.equals(clientSecret)) { clientSecret = value; clearToken(); } }
    public int getPageSize() { return pageSize; }
    public void setPageSize(int value) { pageSize = value > 0 ? value : DEFAULT_PAGE_SIZE; }
    public Duration getTimeout() { return timeout; }
    public void setTimeout(Duration value) { timeout = value; }
    public int getLastStatus() { return lastStatus; }
    public String getAccessToken() { return accessToken; }
    public Instant getTokenExpiry() { return tokenExpiry; }

    /** HTTP client used for every request (default: HttpClient.newHttpClient()). */
    public void setHttpClient(HttpClient client) { httpClient = client; }

    /** SaaS: https://{tenant}.cockpit-itsm.com - on premise: https://{tenant} (a tenant given with its scheme is used as is). */
    public static String baseUrl(boolean saas, String tenant) {
        String result = tenant == null ? "" : tenant.trim();
        while (result.endsWith("/")) {
            result = result.substring(0, result.length() - 1);
        }
        if (saas) {
            return "https://" + result + ".cockpit-itsm.com";
        }
        return result.contains("://") ? result : "https://" + result;
    }

    public String getBaseUrl() {
        return baseUrl(saas, tenant);
    }

    // ------------------------------------------------------------------ token

    public boolean isTokenValid() {
        return !accessToken.isEmpty() && Instant.now().isBefore(tokenExpiry);
    }

    public void clearToken() {
        accessToken = "";
        tokenExpiry = Instant.EPOCH;
    }

    /** Reuse a token obtained by another instance (e.g. one instance per thread). */
    public void setToken(String token, Instant expiry) {
        accessToken = token == null ? "" : token;
        tokenExpiry = expiry == null ? Instant.EPOCH : expiry;
    }

    /** OAuth 2.0 client_credentials (multipart/form-data, scope public-api). */
    public void authenticate() {
        clearToken();
        if (tenant.isEmpty() || clientId.isEmpty() || clientSecret.isEmpty()) {
            throw new CockpitItsmException(0, "Cockpit ITSM: tenant, ClientId and ClientSecret are required", "");
        }
        String boundary = "----CockpitItsm" + System.currentTimeMillis();
        String body = part(boundary, "grant_type", "client_credentials") + part(boundary, "client_id", clientId)
            + part(boundary, "client_secret", clientSecret) + part(boundary, "scope", "public-api")
            + "--" + boundary + "--\r\n";
        HttpResponse<String> resp = send("POST", getBaseUrl() + "/oauth2/token",
            "multipart/form-data; boundary=" + boundary, body, false);
        lastStatus = resp.statusCode();
        if (resp.statusCode() != 200) {
            throw error(resp.statusCode(), resp.body());
        }
        JSONObject obj = asObj(parse(resp.body()));
        String token = obj == null ? null : jStr(obj, "access_token");
        if (token == null || token.isEmpty()) {
            throw new CockpitItsmException(resp.statusCode(), "Cockpit ITSM: no token in the response", resp.body());
        }
        Long expires = jLong(obj, "expires_in");
        long seconds = expires == null ? 3600 : expires;
        if (seconds > 2 * TOKEN_MARGIN_SEC) {
            seconds -= TOKEN_MARGIN_SEC;
        }
        accessToken = token;
        tokenExpiry = Instant.now().plusSeconds(seconds);
    }

    private static String part(String boundary, String name, String value) {
        return "--" + boundary + "\r\nContent-Disposition: form-data; name=\"" + name + "\"\r\n\r\n" + value + "\r\n";
    }

    // ------------------------------------------------------------------ calls

    /** Authenticated call; re-authenticates once on 401; throws CockpitItsmException on a non-2xx status. */
    public String call(String method, String pathQuery, String body) {
        if (!isTokenValid()) {
            authenticate();
        }
        HttpResponse<String> resp = send(method, getBaseUrl() + pathQuery, "application/json", body, true);
        if (resp.statusCode() == 401) {
            authenticate();
            resp = send(method, getBaseUrl() + pathQuery, "application/json", body, true);
        }
        lastStatus = resp.statusCode();
        if (resp.statusCode() < 200 || resp.statusCode() > 299) {
            throw error(resp.statusCode(), resp.body());
        }
        return resp.body();
    }

    public String call(String method, String pathQuery) {
        return call(method, pathQuery, null);
    }

    /** Parsed JSON response: JSONObject, JSONArray, other value, or null for an empty response. */
    public Object callJson(String method, String pathQuery, String body) {
        return parse(call(method, pathQuery, body));
    }

    /**
     * Read every page of a paged list. pagePath = dot-separated members leading from body to
     * the object holding "page" / "pageSize" ("" = body itself, created if missing). Pages are
     * 0-based. Returns the merged "content" items, truncated to totalNumberOfElements.
     */
    public JSONArray fetchAllPages(String method, String pathQuery, JSONObject body, String pagePath) {
        JSONObject pageObj = body;
        if (pagePath != null && !pagePath.isEmpty()) {
            for (String member : pagePath.split("\\.")) {
                JSONObject child = pageObj.optJSONObject(member);
                if (child == null) {
                    child = new JSONObject();
                    pageObj.put(member, child);
                }
                pageObj = child;
            }
        }
        JSONArray result = new JSONArray();
        int page = 0;
        long totalPages = 1;
        long total = -1;
        do {
            pageObj.put("page", page);
            pageObj.put("pageSize", pageSize);
            Object resp = callJson(method, pathQuery, body.toString());
            JSONObject respObj = asObj(resp);
            if (respObj == null) {
                throw new CockpitItsmException(0, "Cockpit ITSM: invalid paged response", String.valueOf(resp));
            }
            if (page == 0) {
                Long n = jLong(respObj, "totalNumberOfPages");
                totalPages = n == null ? 1 : n;
                n = jLong(respObj, "totalNumberOfElements");
                total = n == null ? -1 : n;
            }
            JSONArray content = respObj.optJSONArray("content");
            if (content == null || content.length() == 0) {
                break;
            }
            for (int i = 0; i < content.length(); i++) {
                result.put(content.get(i));
            }
            page++;
        } while (page < totalPages);
        if (total >= 0) {
            while (result.length() > total) {
                result.remove(result.length() - 1);
            }
        }
        return result;
    }

    private HttpResponse<String> send(String method, String url, String contentType, String body, boolean auth) {
        if (httpClient == null) {
            httpClient = HttpClient.newHttpClient();
        }
        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(url)).timeout(timeout)
            .header("Accept", "application/json");
        if (auth) {
            b.header("Authorization", "Bearer " + accessToken);
        }
        if (body != null && !body.isEmpty()) {
            b.header("Content-Type", contentType + (contentType.startsWith("application/json") ? "; charset=utf-8" : ""));
            b.method(method, HttpRequest.BodyPublishers.ofString(body, StandardCharsets.UTF_8));
        } else if ("POST".equals(method) || "PUT".equals(method) || "PATCH".equals(method)) {
            b.header("Content-Type", contentType);
            b.method(method, HttpRequest.BodyPublishers.ofString("", StandardCharsets.UTF_8));
        } else {
            b.method(method, HttpRequest.BodyPublishers.noBody());
        }
        try {
            return httpClient.send(b.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new CockpitItsmException(0, "Cockpit ITSM: request interrupted (" + url + ")", "", e);
        } catch (Exception e) {
            throw new CockpitItsmException(0, "Cockpit ITSM: " + e.getClass().getSimpleName() + " - "
                + e.getMessage() + " (" + url + ")", "", e);
        }
    }

    private static CockpitItsmException error(int status, String response) {
        String msg = "";
        Object v;
        try {
            v = parse(response);
        } catch (CockpitItsmException e) {
            v = null;
        }
        JSONObject o = asObj(v);
        if (o != null) {
            msg = firstNonEmpty(jStr(o, "errorMessage"), jStr(o, "error_description"), jStr(o, "error"));
        }
        if (msg.isEmpty()) {
            msg = response == null ? "" : response.trim();
            if (msg.length() > 300) {
                msg = msg.substring(0, 300) + "...";
            }
        }
        return new CockpitItsmException(status, "Cockpit ITSM: HTTP error " + status + " - " + msg, response);
    }

    private static String firstNonEmpty(String... values) {
        for (String s : values) {
            if (s != null && !s.isEmpty()) {
                return s;
            }
        }
        return "";
    }

    // ------------------------------------------------------------------ URL helpers

    public static String urlEncode(String value) {
        return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8).replace("+", "%20");
    }

    public static void addQuery(StringBuilder query, String name, String value) {
        query.append(query.length() == 0 ? '?' : '&').append(urlEncode(name)).append('=').append(urlEncode(value));
    }

    public static String qDouble(Double value) {
        return BigDecimal.valueOf(value).stripTrailingZeros().toPlainString();
    }

    // ------------------------------------------------------------------ dates

    /** ISO 8601 date-time (Z, +hh:mm, +hhmm or no offset = UTC) -> Instant; null if empty or invalid. */
    public static Instant parseDateTime(String value) {
        if (value == null || value.trim().length() < 10) {
            return null;
        }
        String s = value.trim();
        try {
            if (s.length() == 10) {
                return LocalDate.parse(s).atStartOfDay(ZoneOffset.UTC).toInstant();
            }
            // +0000 -> +00:00
            if (s.matches(".*[+-]\\d{4}$")) {
                s = s.substring(0, s.length() - 2) + ":" + s.substring(s.length() - 2);
            }
            if (s.endsWith("Z") || s.matches(".*[+-]\\d{2}:\\d{2}$")) {
                return DateTimeFormatter.ISO_OFFSET_DATE_TIME.parse(s, Instant::from);
            }
            return java.time.LocalDateTime.parse(s).toInstant(ZoneOffset.UTC);
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    public static LocalDate parseDate(String value) {
        if (value == null || value.trim().length() < 10) {
            return null;
        }
        try {
            return LocalDate.parse(value.trim().substring(0, 10));
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    /** Instant -> UTC ISO 8601 with milliseconds ("2026-11-02T14:30:00.000Z"). */
    public static String formatDateTime(Instant value) {
        return DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'").withZone(ZoneOffset.UTC).format(value);
    }

    public static String formatDate(LocalDate value) {
        return value.toString();
    }

    // ------------------------------------------------------------------ JSON: parsing

    /** JSON text -> JSONObject / JSONArray / other value; null for empty text. */
    public static Object parse(String text) {
        if (text == null || text.trim().isEmpty()) {
            return null;
        }
        try {
            Object v = new JSONTokener(text).nextValue();
            return v == JSONObject.NULL ? null : v;
        } catch (RuntimeException e) {
            throw new CockpitItsmException(0, "Invalid JSON response: " + e.getMessage(), text, e);
        }
    }

    public static JSONObject asObj(Object value) {
        return value instanceof JSONObject ? (JSONObject) value : null;
    }

    public static JSONArray asArr(Object value) {
        return value instanceof JSONArray ? (JSONArray) value : null;
    }

    /** Text of a JSON string response ("abc" -> abc), other text unchanged. */
    public static String unquote(String text) {
        if (text == null) {
            return null;
        }
        String s = text.trim();
        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
            Object v = parse(s);
            return v instanceof String ? (String) v : s;
        }
        return text;
    }

    // ------------------------------------------------------------------ JSON: values (null if missing, null or invalid)

    private static Object val(JSONObject obj, String name) {
        if (obj == null) {
            return null;
        }
        Object v = obj.opt(name);
        return v == JSONObject.NULL ? null : v;
    }

    public static String toStr(Object v) {
        if (v == null || v == JSONObject.NULL) {
            return null;
        }
        return v instanceof String ? (String) v : v.toString();
    }

    public static Integer toInt(Object v) {
        if (v instanceof Number) {
            return ((Number) v).intValue();
        }
        if (v instanceof String) {
            try {
                return Integer.valueOf(((String) v).trim());
            } catch (NumberFormatException e) {
                return null;
            }
        }
        return null;
    }

    public static Long toLong(Object v) {
        if (v instanceof Number) {
            return ((Number) v).longValue();
        }
        if (v instanceof String) {
            try {
                return Long.valueOf(((String) v).trim());
            } catch (NumberFormatException e) {
                return null;
            }
        }
        return null;
    }

    public static Double toDouble(Object v) {
        if (v instanceof Number) {
            return ((Number) v).doubleValue();
        }
        if (v instanceof String) {
            try {
                return Double.valueOf(((String) v).trim());
            } catch (NumberFormatException e) {
                return null;
            }
        }
        return null;
    }

    public static Boolean toBool(Object v) {
        if (v instanceof Boolean) {
            return (Boolean) v;
        }
        if (v instanceof String) {
            return "true".equalsIgnoreCase(((String) v).trim());
        }
        return null;
    }

    public static Instant toDateTime(Object v) {
        return v instanceof String ? parseDateTime((String) v) : null;
    }

    public static LocalDate toDate(Object v) {
        return v instanceof String ? parseDate((String) v) : null;
    }

    /** JSON text of a value (raw members). */
    public static String toRaw(Object v) {
        if (v == null || v == JSONObject.NULL) {
            return null;
        }
        if (v instanceof String) {
            return JSONObject.quote((String) v);
        }
        return v.toString();
    }

    public static String jStr(JSONObject obj, String name) { return toStr(val(obj, name)); }
    public static Integer jInt(JSONObject obj, String name) { return toInt(val(obj, name)); }
    public static Long jLong(JSONObject obj, String name) { return toLong(val(obj, name)); }
    public static Double jDouble(JSONObject obj, String name) { return toDouble(val(obj, name)); }
    public static Boolean jBool(JSONObject obj, String name) { return toBool(val(obj, name)); }
    public static Instant jDateTime(JSONObject obj, String name) { return toDateTime(val(obj, name)); }
    public static LocalDate jDate(JSONObject obj, String name) { return toDate(val(obj, name)); }
    public static String jRaw(JSONObject obj, String name) { return toRaw(val(obj, name)); }
    public static JSONObject jObj(JSONObject obj, String name) { return asObj(val(obj, name)); }
    public static JSONArray jArr(JSONObject obj, String name) { return asArr(val(obj, name)); }

    // ------------------------------------------------------------------ JSON: lists

    /** List of the converted items of a JSON array; null if the array is missing. */
    public static <T> List<T> list(JSONArray arr, Function<Object, T> conv) {
        if (arr == null) {
            return null;
        }
        List<T> result = new ArrayList<>(arr.length());
        for (int i = 0; i < arr.length(); i++) {
            Object v = arr.opt(i);
            result.add(conv.apply(v == JSONObject.NULL ? null : v));
        }
        return result;
    }

    /** JSON array of the converted items of a list (null items kept as JSON null). */
    public static <T> JSONArray array(List<T> items, Function<T, Object> conv) {
        JSONArray result = new JSONArray();
        if (items != null) {
            for (T item : items) {
                Object v = item == null ? null : conv.apply(item);
                result.put(v == null ? JSONObject.NULL : v);
            }
        }
        return result;
    }

    // ------------------------------------------------------------------ JSON: writing (null values are not written)

    public static void put(JSONObject obj, String name, Object value) {
        if (value == null) {
            return;
        }
        if (value instanceof Instant) {
            obj.put(name, formatDateTime((Instant) value));
        } else if (value instanceof LocalDate) {
            obj.put(name, formatDate((LocalDate) value));
        } else {
            obj.put(name, value);
        }
    }

    /** Raw member: JSON text inserted as a value. */
    public static void putRaw(JSONObject obj, String name, String json) {
        if (json == null || json.trim().isEmpty()) {
            return;
        }
        Object v = new JSONTokener(json).nextValue();
        obj.put(name, v);
    }

    public static Object fromDateTime(Instant value) {
        return value == null ? null : formatDateTime(value);
    }

    public static Object fromDate(LocalDate value) {
        return value == null ? null : formatDate(value);
    }
}
